let theShader;

function preload(){
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  noStroke();
}

function draw() {
	 background(0);
	 shader(theShader);

	theShader.setUniform("uFrameCount", frameCount);


  rotateX(frameCount * 0.002);
  rotateY(frameCount * 0.001);

  sphere(height / 2.8, 800, 500);
  //print(frameRate());
}

function windowResized(){
  resizeCanvas(windowWidth, windowHeight);
}

// === Tab: shader.vert ===
let vert = `
precision mediump float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;

uniform mat4 uProjectionMatrix; 
uniform mat4 uModelViewMatrix; 
uniform float uFrameCount;

varying vec2 vTexCoord;
varying vec3 vNormal;
varying vec3 vPosition; 

void main() {

  vec3 delta = 0.1 *  aNormal * sin(aPosition * 30. + uFrameCount * 0.1); 
  vPosition = aPosition + delta ;  
  vNormal = normalize(aNormal + delta);
  vTexCoord = aTexCoord; 
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(vPosition, 1.); 

}


`;

// === Tab: shader.frag ===
let frag = `
precision mediump float;

uniform mat4 uProjectionMatrix; 
uniform mat4 uModelViewMatrix; 
uniform float uFrameCount;

varying vec2 vTexCoord; 
varying vec3 vNormal;
varying vec3 vPosition; 

void main() {

	 vec3 ambientColor = vec3(0.0, 0.0, 1.0);
	 vec3 diffuseColor = vec3(0.0, 1.0, 0.0);
	 vec3 specularColor = vec3(1.0, 0.0, 0.0);

	 float time = uFrameCount *  0.1;
	 vec3 lightPos = vec3(-50. * cos(time), 20.* sin(time), -50.);
	 vec3 lightDir = normalize(lightPos - vPosition);
	 float lambertian = max(dot(-vNormal, lightDir), 0.0);
	 float specular = 0.0; 
   if(lambertian > 0.0) {
     vec3 reflectLight = reflect(-lightDir, vNormal); 
     vec3 viewerDir = normalize(-vPosition);
    float specAngle = max(dot(reflectLight, viewerDir), 0.0);
    specular = pow(specAngle, 128.);
  }
  gl_FragColor = vec4(ambientColor + lambertian * diffuseColor + specular * specularColor, 1.0);

}


`;

